from pathlib import Path
p=Path('C:/Users/admin/.codex/visualizations/2026/10/07/01a113f3-1f33-7d40-bf39-7aaed264b0b9/custom-activity.html')
s=p.read_text(encoding='utf-8')
style=s[s.index('<style>'):s.index('</style>')+8]
content='''<div id="custom-activity">STYLE<header><strong>卓希综合管理系统</strong><span class="crm">CRM系统</span><span>费用管理 / 活动执行填报</span></header><main style="padding:24px"><div class="heading"><h1>活动执行填报</h1><span class="status">待填报 · 演示数据</span></div><form id="execution"><section><h2>关联活动申请</h2><div class="grid"><label>申请单号<input readonly value="示例申请单 HD-DEMO-001"></label><label>活动名称<input readonly value="连锁系统团购专项支持"></label><label>申请状态<input readonly value="已审批（示例）"></label><label>经销商<input readonly value="示例经销商有限公司"></label><label>系统 / 客户<input readonly value="示例连锁系统"></label><label>计划执行日期<input readonly value="2026-10-01 至 2026-11-30"></label></div><small>独立演示页面，关联信息需在正式系统中由已审批申请自动带入。</small></section><section><h2>实际执行情况</h2><div class="grid"><label><span><em>*</em> 实际开始日期</span><input required id="begin" type="date"></label><label><span><em>*</em> 实际结束日期</span><input required id="finish" type="date"></label><label><span><em>*</em> 执行状态</span><select id="state"><option>已完成</option><option>部分执行</option><option>未执行</option></select></label><label class="wide"><span><em>*</em> 执行情况说明</span><textarea required placeholder="填写实际执行内容、完成情况及与申请方案的差异"></textarea></label></div></section><section><h2>门店执行数据</h2><small>正式系统带入申请门店。未执行门店仍保留记录并填写原因。</small><div class="table-wrap"><table><thead><tr><th>门店名称</th><th>执行情况</th><th>实际销售额（元）</th><th>执行说明 / 未执行原因</th></tr></thead><tbody id="stores"></tbody></table></div></section><section><h2>实际费用与承担</h2><small>费用项、承担比例及结算方式沿用已审批申请。填写实际发生金额。</small><div class="table-wrap"><table><thead><tr><th>费用项</th><th>申请预算（元）</th><th>实际费用（元）*</th><th>我司承担%</th><th>结算方式</th><th>费用说明</th></tr></thead><tbody id="costs"></tbody></table></div><div class="summary" aria-live="polite"><div><small>申请费用总额（元）</small><b>1,746.88</b></div><div><small>实际费用总额（元）</small><b id="actual">0.00</b></div><div><small>与预算差异（元）</small><b id="difference">-1,746.88</b></div><div><small>实际我司费销比</small><b id="ratio">不适用</b></div></div><div class="grid"><label>实际我司承担（元）<input readonly id="company"></label><label>实际经销商承担（元）<input readonly value="0.00"></label><label>实际销售额合计（元）<input readonly id="sales"></label><label class="wide">差异原因说明<textarea id="reason" placeholder="预算不一致、门店未执行或方案调整时填写原因"></textarea></label></div></section><div class="footer"><span class="muted">填报实际数据后提交审核。</span><div class="row"><button type="button" id="save">保存草稿</button><button class="primary">提交执行数据</button></div></div><div id="feedback" role="status" aria-live="polite"></div></form></main><script>
(()=>{const q=s=>document.querySelector(s),money=n=>n.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});['示例门店 · 中心店','示例门店 · 城东店'].forEach(name=>{const tr=document.createElement('tr');tr.innerHTML='<td>'+name+'</td><td><select class="store-state"><option>已执行</option><option>未执行</option></select></td><td><input aria-label="'+name+'实际销售额" class="sale" type="number" min="0" step="0.01" placeholder="无销售数据可留空"></td><td><input class="store-note" aria-label="'+name+'执行说明"></td>';q('#stores').append(tr)});[['团购奖励',1600],['第三方服务费',48],['发票税费',98.88]].forEach(([name,budget])=>{const tr=document.createElement('tr');tr.innerHTML='<td>'+name+'</td><td>'+money(budget)+'</td><td><input required class="amount" aria-label="'+name+'实际金额" type="number" min="0" step="0.01" placeholder="请填写"></td><td>100%</td><td>对公付款</td><td><input aria-label="'+name+'费用说明"></td>';q('#costs').append(tr)});function calc(){const total=Array.from(document.querySelectorAll('.amount')).reduce((a,e)=>a+Number(e.value),0),sales=Array.from(document.querySelectorAll('.sale')).reduce((a,e)=>a+Number(e.value),0);q('#actual').textContent=money(total);q('#difference').textContent=(total>1746.88?'+':'')+money(total-1746.88);q('#company').value=money(total);q('#sales').value=money(sales);q('#ratio').textContent=sales>0?(total/sales*100).toFixed(2)+'%':'不适用';return total}q('#execution').addEventListener('input',calc);q('#save').onclick=()=>{const data=Array.from(q('#execution').elements).map(e=>e.value);try{localStorage.setItem('activity-execution-draft',JSON.stringify(data));q('#feedback').textContent='草稿已保存在当前浏览器。'}catch{q('#feedback').textContent='浏览器无法保存，请保留页面后重试。'}};try{const data=JSON.parse(localStorage.getItem('activity-execution-draft'));if(Array.isArray(data))Array.from(q('#execution').elements).forEach((e,i)=>{if(data[i]!=null)e.value=data[i]})}catch{}q('#execution').onsubmit=e=>{e.preventDefault();let error='';if(q('#finish').value<q('#begin').value)error='实际结束日期不能早于开始日期。';else if(Array.from(q('#stores').rows).some(r=>r.querySelector('select').value==='未执行'&&!r.querySelector('.store-note').value.trim()))error='请填写未执行门店的原因。';else if(Math.abs(calc()-1746.88)>.005&&!q('#reason').value.trim())error='请填写费用与预算不一致的差异原因。';else if(calc()>1746.88)error='实际费用超出已批预算，请先完成补充审批后再提交。';q('#feedback').className=error?'error':'';q('#feedback').textContent=error||'校验通过。此为演示页面，未提交真实执行数据。'};calc()})();</script></div>'''
fragment=content.replace('STYLE',style)
Path('E:/cxy/活动执行填报.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>活动执行填报</title><body style="margin:16px">'+fragment+'</body></html>',encoding='utf-8')
